async function captureOne(page,spec,state){return page.evaluate(({kind,state})=>{const round=n=>Math.round(n*1000)/1000,pick=sel=>{const el=document.querySelector(sel);if(!el)return null;const s=getComputedStyle(el),r=el.getBoundingClientRect();return{display:s.display,width:s.width,height:s.height,minWidth:s.minWidth,minHeight:s.minHeight,maxWidth:s.maxWidth,maxHeight:s.maxHeight,gap:s.gap,padding:s.padding,borderRadius:s.borderRadius,boxShadow:s.boxShadow,fontSize:s.fontSize,lineHeight:s.lineHeight,overflow:s.overflow,rect:[round(r.x),round(r.y),round(r.width),round(r.height)]}};const b=getComputedStyle(document.body);return{page:kind==='messages'?'mensagens.html':'comunidade-interna.html',state,vars:{control:b.getPropertyValue('--chat-control-size').trim(),radius:b.getPropertyValue('--chat-control-radius').trim(),icon:b.getPropertyValue('--chat-control-icon').trim(),search:b.getPropertyValue('--chat-search-height').trim(),avatar:b.getPropertyValue('--chat-avatar-size').trim(),cardRadius:b.getPropertyValue('--chat-card-radius').trim(),cardGap:b.getPropertyValue('--chat-card-gap').trim(),directMin:b.getPropertyValue('--chat-direct-card-min-height').trim(),channelMin:b.getPropertyValue('--chat-channel-card-min-height').trim(),memberMin:b.getPropertyValue('--chat-member-card-min-height').trim()},search:pick(kind==='messages'?'.messages-sidebar-search':'.community-room-search'),messageCard:pick('.message-item'),communityCard:pick('.community-room-channel'),content:pick('.message-item__content'),strong:pick('.message-item__line strong'),preview:pick(kind==='messages'?'.message-item__preview':'.community-room-channel__preview'),deal:pick('.message-item__deal-status'),action:pick('.messages-thread__action--order, .messages-thread__action--charge, .community-room-thread__action:not(.community-room-thread__action--icon)'),bubble:pick('.message-bubble'),sharedCard:pick('.message-item, .community-room-channel, .community-room-online-list > span'),doc:{clientWidth:document.documentElement.clientWidth,scrollWidth:document.documentElement.scrollWidth,bodyScrollWidth:document.body.scrollWidth}}},{kind:spec.kind,state})}
function verifyCoverage(snaps){const vals=Object.values(snaps),has=k=>vals.some(s=>s[k]!==null);for(const k of ['search','messageCard','communityCard','content','strong','preview','deal','action','bubble','sharedCard'])assert(has(k),`runtime family not covered ${k}`);assert(vals.every(s=>s.vars&&s.vars.control),'root variable family not covered');console.log('RUNTIME FAMILY COVERAGE PASS|families=11/11|dynamicFixture=repository-renderer-anatomy')}
async function capture(browser,tag){const out={};let n=0;for(const spec of PAGES)for(const state of STATES)for(const width of VIEWPORTS){const ctx=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),page=await ctx.newPage();await page.route('**/*',route=>{const u=new URL(route.request().url()),local=u.origin==='http://127.0.0.1:4173';if(local&&u.pathname.endsWith('.js'))return route.abort();if(local||u.protocol==='data:'||u.protocol==='blob:')return route.continue();return route.abort()});await page.goto(`http://127.0.0.1:4173/${spec.page}?ux046-${tag}-${state}-${width}`,{waitUntil:'domcontentloaded',timeout:20000});await prepare(page,spec,state);await page.waitForTimeout(35);const snap=await captureOne(page,spec,state);assert(snap.doc.scrollWidth<=snap.doc.clientWidth+1,`overflow ${tag} ${spec.page} ${state} ${width} ${JSON.stringify(snap.doc)}`);out[`${spec.page}:${state}:${width}`]=snap;n++;await ctx.close()}verifyCoverage(out);console.log(`RUNTIME CAPTURE|tag=${tag}|pages=2|states=2|viewports=${VIEWPORTS.join(',')}|samples=${n}|overflow=0`);return out}
(async()=>{assert(SHA&&BLOB,'missing env');assert(sh('git rev-parse HEAD')===SHA,'wrong HEAD');assert(sh(`git hash-object ${TARGET}`)===BLOB,'blob drift');verifyReach();const parsed=parse(fs.readFileSync(TARGET,'utf8'));verifyDead(parsed);const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{const before=await capture(browser,'before');removeDead(parsed);const after=await capture(browser,'after');assert(JSON.stringify(before)===JSON.stringify(after),'runtime parity mismatch');console.log(`CASCADE RUNTIME PARITY PASS|runtimeDiffs=0|overflow=0|families=11/11|reachPages=2|states=2|viewports=${VIEWPORTS.length}|beforeSamples=${Object.keys(before).length}|afterSamples=${Object.keys(after).length}|boundary=1023/1024/1180/1181|staticCascadeRows=37|identicalWinners=14|changedWinners=23`)}finally{await browser.close()}}finally{server.kill('SIGTERM')}sh(`git reset --hard ${SHA}`);sh('git clean -fdx');assert(sh('git rev-parse HEAD')===SHA&&sh(`git hash-object ${TARGET}`)===BLOB&&sh('git status --porcelain')==='','restore drift');console.log(`CHECKPOINT PASS|sha=${SHA}|productMutation=0|issueCreated=0|prCreated=0`)})().catch(e=>{console.error(e.stack||e);process.exit(1)});
